package com.writingassistant.core.similarity;

import java.util.Collections;
import java.util.List;

/**
 * Detailed report generated by the offline similarity checker.
 */
public class SimilarityReport {

    private final double similarityScore; // 0.0 to 100.0
    private final SimilarityRisk risk;
    private final List<MatchedSpan> matchedSpans;
    private final double nGramOverlap;      // 0.0 to 100.0
    private final double lcsRatio;          // 0.0 to 100.0
    private final double editSimilarity;    // 0.0 to 100.0
    private final boolean offline;

    public SimilarityReport(double similarityScore, SimilarityRisk risk, List<MatchedSpan> matchedSpans,
                            double nGramOverlap, double lcsRatio, double editSimilarity) {
        this.similarityScore = Math.max(0.0, Math.min(100.0, similarityScore));
        this.risk = risk != null ? risk : SimilarityRisk.LOW;
        this.matchedSpans = matchedSpans != null ? List.copyOf(matchedSpans) : Collections.emptyList();
        this.nGramOverlap = Math.max(0.0, Math.min(100.0, nGramOverlap));
        this.lcsRatio = Math.max(0.0, Math.min(100.0, lcsRatio));
        this.editSimilarity = Math.max(0.0, Math.min(100.0, editSimilarity));
        this.offline = true; // Always 100% computed locally without network
    }

    public double getSimilarityScore() {
        return similarityScore;
    }

    public String getScorePercentage() {
        return String.format("%.1f%%", similarityScore);
    }

    public SimilarityRisk getRisk() {
        return risk;
    }

    public List<MatchedSpan> getMatchedSpans() {
        return matchedSpans;
    }

    public double getNGramOverlap() {
        return nGramOverlap;
    }

    public double getLcsRatio() {
        return lcsRatio;
    }

    public double getEditSimilarity() {
        return editSimilarity;
    }

    public boolean isOffline() {
        return offline;
    }

    /**
     * Returns a clear, actionable summary of the similarity findings.
     */
    public String getSummary() {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("Similarity Score: %.1f%% (%s)%n", similarityScore, risk.getLabel()));
        sb.append(String.format("• Word N-Gram Overlap:       %.1f%%%n", nGramOverlap));
        sb.append(String.format("• Longest Common Sequence:   %.1f%%%n", lcsRatio));
        sb.append(String.format("• Edit-Distance Similarity:  %.1f%%%n", editSimilarity));
        sb.append(String.format("• Flagged Overlapping Spans: %d%n", matchedSpans.size()));
        sb.append("Guidance: ").append(risk.getAdvice());
        return sb.toString();
    }

    @Override
    public String toString() {
        return "SimilarityReport{" +
                "score=" + String.format("%.1f%%", similarityScore) +
                ", risk=" + risk +
                ", nGram=" + String.format("%.1f%%", nGramOverlap) +
                ", lcs=" + String.format("%.1f%%", lcsRatio) +
                ", spansCount=" + matchedSpans.size() +
                '}';
    }
}
